remediationSample:
Avoid paths being concatenated with user inputs.
If this is not possible, validate the arguments using a dedicated method and declare this method as a sanitization method for the quality rule. Example of such methods:

// ----------------------------------------------------------------------------
// 1) Java sample

import org.springframework.web.bind.annotation.*;
import java.util.Map;

@RestController
public class LoadLibraryControllerSecure {

  private static final Map<String, String> ALLOWED_LIBS = Map.of(
      "mylib", "mylib",
      "otherlib", "otherlib"
  );

  @GetMapping("/load/secure")
  public void loadLibrary_secure(@RequestParam String userInput) {
    String libPath = getSecureLibraryPath(userInput);
    if (libPath != null) {
      System.loadLibrary(libPath);  // ✓ OK
    }
  }

  private String getSecureLibraryPath(String libName) {
    String path = ALLOWED_LIBS.get(libName);
    if (path != null) {
      return path;
    } else {
      System.err.println("Invalid library specified.");
      return null;
    }
  }
}


// ----------------------------------------------------------------------------
// 2) C# sample

using Confluent.Kafka;
using System.Runtime.InteropServices;

internal class Program
{
  private static Dictionary<string, string> config;

  private static bool LoadLibrary_secure(string userInput)
  {
    // Validate and get secure the library path
    string securePath = GetSecureLibraryPath(userInput);
    if (securePath == null)
    {
      return false;
    }

    if (!System.IO.File.Exists(securePath))
    {
      return false;
    }

    NativeLibrary.Load(securePath); // ✓ OK
    return true;
  }

  private static string GetSecureLibraryPath(string userInput)
  {
    Dictionary<string, string> AllowedLibs = new()
    {
      ["mylib"] = "C:\\libs\\mylib.dll",
      ["otherlib"] = "C:\\libs\\otherlib.dll"
    };

    // White-list + absolute path
    if (AllowedLibs.TryGetValue(userInput, out var path))
    {
      return path;
    }
    else
    {
      Console.Error.WriteLine("Invalid library specified.");
      return null;
    }
  }

  static void Main(string[] args)
  {
    Console.WriteLine("Hello, World!");
    using var consumer = new ConsumerBuilder<Ignore, string>(config).Build();
    consumer.Subscribe("library-topic");
    var result = consumer.Consume(TimeSpan.FromSeconds(10));

    if (result is null)
      return;

    string userInput = result.Message.Value; // Unsafe input from Kafka
    LoadLibrary_secure(userInput);
  }
}

